import assert from "node:assert/strict";
import { test } from "node:test";
import {
  type Canvas,
  type CanvasAction,
  canvasReducer,
  clampZoom,
  cssLength,
  FRAME_HEIGHT,
  fit,
  inlineMarkup,
  LEGIBLE,
  MAX_ZOOM,
  MIN_ZOOM,
  naturalSize,
  openCanvas,
  percent,
  READABLE,
  STEP,
} from "./drawing.ts";

const graphviz = `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN"
 "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">
<!-- Generated by graphviz -->
<svg width="62pt" height="116pt"
 viewBox="0.00 0.00 62.00 116.00" xmlns="http://www.w3.org/2000/svg">
<g id="graph0" class="graph"><g id="n3" class="node" width="9pt"></g></g>
</svg>
`;

test("the zoom stays between its bounds", () => {
  assert.equal(clampZoom(0), MIN_ZOOM);
  assert.equal(clampZoom(100), MAX_ZOOM);
  assert.equal(clampZoom(0.5), 0.5);
});

test("a zoom reads in whole percents, or tenths below ten percent", () => {
  assert.equal(percent(1), "100%");
  assert.equal(percent(STEP * STEP), "156%");
  assert.equal(percent(0.6), "60%");
  assert.equal(percent(0.1), "10%");
  assert.equal(percent(0.019), "1.9%");
  assert.equal(percent(MIN_ZOOM), "1.0%");
});

test("the inline markup starts at the svg element", () => {
  assert.ok(inlineMarkup(graphviz).startsWith("<svg width="));
  assert.ok(inlineMarkup(graphviz).endsWith("</svg>\n"));
  assert.equal(inlineMarkup("<p>no drawing</p>"), "<p>no drawing</p>");
});

test("lengths in points are converted to pixels", () => {
  assert.equal(cssLength("12pt"), 16);
  assert.equal(cssLength("1.5pt"), 2);
  assert.equal(cssLength("12px"), 12);
  assert.equal(cssLength("12"), 12);
  assert.equal(cssLength("12em"), null);
  assert.equal(cssLength("100%"), null);
  assert.equal(cssLength(""), null);
  assert.equal(cssLength(undefined), null);
});

test("the natural size is read from the svg element's own attributes", () => {
  assert.deepEqual(naturalSize(graphviz), {
    w: (62 * 4) / 3,
    h: (116 * 4) / 3,
  });
  // The width of an element inside the drawing, or one that only ends in
  // `width`, is not the drawing's.
  assert.deepEqual(
    naturalSize(
      '<svg stroke-width="3" viewBox="0 0 40 30"><g width="9"/></svg>',
    ),
    { w: 40, h: 30 },
  );
});

test("without a usable width and height the view box gives the size", () => {
  assert.deepEqual(naturalSize('<svg viewBox="0,0,40,30"></svg>'), {
    w: 40,
    h: 30,
  });
  assert.deepEqual(
    naturalSize('<svg width="100%" height="50pt" viewBox=" 0 0 40 30 "/>'),
    { w: 40, h: 30 },
  );
  assert.deepEqual(
    naturalSize('<svg width="0" height="50" viewBox="0 0 40 30"/>'),
    { w: 40, h: 30 },
  );
  assert.equal(naturalSize('<svg viewBox="0 0 40 0"/>'), null);
  assert.equal(naturalSize('<svg width="100%" height="100%"/>'), null);
  assert.equal(naturalSize("no drawing"), null);
});

test("a fit shows the whole drawing in the frame's width and grown height", () => {
  // The frame grows to FRAME_HEIGHT of the window.
  const window = 1000;
  const height = window * FRAME_HEIGHT;
  assert.equal(fit({ w: 100, h: 100 }, 800, window), 1);
  assert.equal(fit({ w: 1600, h: 100 }, 800, window), 0.5);
  assert.equal(fit({ w: 100, h: height * 4 }, 800, window), 0.25);
  assert.equal(fit({ w: 1600, h: height * 4 }, 800, window), 0.25);
  assert.equal(fit({ w: 800 * 1000, h: 100 }, 800, window), MIN_ZOOM);
});

const middle = { x: 300, y: 100 };

function after(state: Canvas, ...actions: CanvasAction[]): Canvas {
  return actions.reduce(canvasReducer, state);
}

test("a canvas opens at its place's zoom, unplaced and unmoved", () => {
  assert.deepEqual(openCanvas(null), {
    zoom: 1,
    tooLarge: false,
    placed: false,
    move: null,
  });
  assert.equal(openCanvas({ zoom: 0.25, left: 10, top: 20 }).zoom, 0.25);
});

test("a drawing seen before is placed without a move", () => {
  const opened = openCanvas({ zoom: 0.25, left: 10, top: 20 });
  assert.deepEqual(after(opened, { type: "place", fit: null }), {
    ...opened,
    placed: true,
  });
});

test("a new drawing is placed fitted, but no smaller than readable", () => {
  const seed = { x: 80, y: 40 };
  const fitted = after(openCanvas(null), {
    type: "place",
    fit: { zoom: 0.8, seed },
  });
  assert.deepEqual(fitted, {
    zoom: 0.8,
    tooLarge: false,
    placed: true,
    move: { center: seed },
  });
  const wide = after(openCanvas(null), {
    type: "place",
    fit: { zoom: 0.2, seed: null },
  });
  assert.equal(wide.zoom, READABLE);
  assert.equal(wide.tooLarge, false);
  // Without a seed on show the scroll stays, but the move is still made,
  // so the place is remembered.
  assert.deepEqual(wide.move, { center: null });
  const huge = after(openCanvas(null), {
    type: "place",
    fit: { zoom: LEGIBLE / 2, seed: null },
  });
  assert.equal(huge.zoom, READABLE);
  assert.equal(huge.tooLarge, true);
});

test("a seed is unscaled by the zoom it was measured at", () => {
  const opened = openCanvas({ zoom: 2, left: 0, top: 0 });
  const placed = after(opened, {
    type: "place",
    fit: { zoom: 1, seed: { x: 80, y: 40 } },
  });
  assert.deepEqual(placed.move, { center: { x: 40, y: 20 } });
});

test("a drawing is placed once", () => {
  const placed = after(openCanvas(null), {
    type: "place",
    fit: { zoom: 0.8, seed: null },
  });
  assert.equal(
    canvasReducer(placed, { type: "place", fit: { zoom: 0.3, seed: null } }),
    placed,
  );
  assert.equal(canvasReducer(placed, { type: "place", fit: null }), placed);
});

test("zooming keeps the middle of the frame, unscaled by the zoom before", () => {
  const placed = after(openCanvas(null), { type: "place", fit: null });
  const zoomed = after(placed, { type: "zoom", to: 2, middle });
  assert.deepEqual(zoomed, {
    ...placed,
    zoom: 2,
    move: { center: middle },
  });
  assert.deepEqual(after(zoomed, { type: "zoom", to: 1, middle }).move, {
    center: { x: 150, y: 50 },
  });
});

test("zooming in and out steps by STEP within the bounds", () => {
  const start = openCanvas(null);
  assert.equal(after(start, { type: "zoom", to: "in", middle }).zoom, STEP);
  assert.equal(
    after(start, { type: "zoom", to: "out", middle }).zoom,
    1 / STEP,
  );
  assert.equal(
    after(
      start,
      { type: "zoom", to: "in", middle },
      { type: "zoom", to: "in", middle },
      { type: "zoom", to: "out", middle },
    ).zoom,
    STEP,
  );
  assert.equal(
    after(
      start,
      { type: "zoom", to: MAX_ZOOM, middle },
      {
        type: "zoom",
        to: "in",
        middle,
      },
    ).zoom,
    MAX_ZOOM,
  );
  assert.equal(after(start, { type: "zoom", to: 0, middle }).zoom, MIN_ZOOM);
});

test("zooming to the zoom on show is still a move", () => {
  const start = openCanvas(null);
  const once = after(start, { type: "zoom", to: 1, middle });
  const twice = after(once, { type: "zoom", to: 1, middle });
  assert.equal(twice.zoom, 1);
  assert.notEqual(twice.move, once.move);
  assert.deepEqual(twice.move, once.move);
});

test("a fit is not floored and says whether it is legible", () => {
  const placed = after(openCanvas(null), { type: "place", fit: null });
  const tiny = after(placed, { type: "fit", zoom: LEGIBLE / 2, middle });
  assert.deepEqual(tiny, {
    zoom: LEGIBLE / 2,
    tooLarge: true,
    placed: true,
    move: { center: middle },
  });
  const legible = after(tiny, { type: "fit", zoom: 0.2, middle });
  assert.equal(legible.zoom, 0.2);
  assert.equal(legible.tooLarge, false);
  assert.deepEqual(legible.move, {
    center: { x: middle.x / (LEGIBLE / 2), y: middle.y / (LEGIBLE / 2) },
  });
  // Zooming afterwards keeps what the last fit said.
  assert.equal(after(tiny, { type: "zoom", to: 1, middle }).tooLarge, true);
});
